mapper.update:

UPDATE sa
SET sa.attendance_key = 'late' FROM erp_student_attendance AS sa
WHERE sa.attendance_date = #{attendanceDate}
  AND sa.in_time IS NOT NULL
  AND sa.in_time
    > (
    SELECT t.start_time
    FROM erp_time_table AS t
    WHERE t.time_table_key = #{timeTableKey}
    )
  AND sa.student_id IN (
    SELECT s.student_id
    FROM erp_time_table_assign AS ta
    JOIN erp_student AS s ON s.student_id = ta.student_id
    WHERE ta.time_table_key = #{timeTableKey}
    )

mapper.delete:
DELETE FROM erp_remedial
WHERE student_id = #{studentId}
  AND time_table_key = #{timeTableKey}
  AND week = #{week}

mapper.select:
SELECT start_time
FROM erp_time_table
WHERE time_table_key = #{timeTableKey}
